{
  "flow": {
    "name": "Sarkari Exam AI",
    "url": "https://app.banani.co/flow/wqucLs7TJesh",
    "id": "wqucLs7TJesh"
  },
  "designs": [
    {
      "screenId": "wqucLs7TJesh/screens/new_screen3.jsx",
      "screenName": "Home Dashboard (Mobile)",
      "source": "import Icon from '@global/Icon';
import TopNav from '@components/TopNav';
import BottomNav from '@components/BottomNav';

export const displayName = 'Home Dashboard (Mobile)';
export const screenSize = 'mobile';

export default function HomeDashboardScreen() {
  const gridFeatures = [
    { title: t('Mock Tests'), icon: 'file-edit', color: 'text-blue-600', bg: 'bg-blue-50' },
    { title: t('PYQ Practice'), icon: 'history', color: 'text-purple-600', bg: 'bg-purple-50' },
    { title: t('Topic-wise Tests'), icon: 'book-open', color: 'text-green-600', bg: 'bg-green-50' },
    { title: t('Daily Quiz'), icon: 'clock', color: 'text-orange-600', bg: 'bg-orange-50' },
    { title: t('Full-Length Tests'), icon: 'target', color: 'text-red-600', bg: 'bg-red-50' },
    { title: t('AI Test Generator'), icon: 'sparkles', color: 'text-indigo-600', bg: 'bg-indigo-50' },
  ];

  const weakTopics = [
    { subject: t('Quantitative Aptitude'), score: 45, color: 'bg-error' },
    { subject: t('English Comprehension'), score: 62, color: 'bg-warning' },
    { subject: t('General Intelligence'), score: 85, color: 'bg-success' },
  ];

  return (
    <div className="flex flex-col min-h-screen bg-background relative mobile-screen">

      {/* Custom Top Navigation for Home */}
      <header className="flex items-center justify-between px-4 py-3 bg-primary text-primary-foreground z-20">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-white/20 rounded-full flex items-center justify-center">
            <Icon i="user" size={18} />
          </div>
          <div className="flex flex-col">
            <span className="text-[10px] text-white/80 uppercase font-bold tracking-wider">{t('Welcome Back')}</span>
            <span className="font-headings font-bold text-sm leading-tight">{t('Aarav Sharma')}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button className="relative bg-white/20 p-2 rounded-full">
            <Icon i="bell" size={18} />
            <div className="absolute top-0 right-0 w-2.5 h-2.5 bg-error rounded-full border-2 border-primary"></div>
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto pb-6">

        {/* Top Header Area (Greeting & Target Exam) */}
        <div className="bg-primary pt-4 pb-24 px-4 text-primary-foreground relative z-0">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-2xl font-headings font-bold mb-1 flex items-center gap-2">
                {t('Hello, Aspirant')} 👋
              </h1>
              <p className="text-primary-foreground/80 text-sm">
                {t('Prepare smarter with AI')}
              </p>
            </div>
          </div>

          {/* Search Bar */}
          <div className="relative mt-2">
            <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-muted-foreground">
              <Icon i="search" size={18} />
            </div>
            <div className="w-full pl-10 pr-4 py-2.5 bg-white rounded-xl text-sm text-muted-foreground flex items-center shadow-sm">
              {t('Search for exams, notes, PYQs...')}
            </div>
          </div>
        </div>

        {/* Overlapping Content Box */}
        <div className="px-4 -mt-16 relative z-10 space-y-5">

          {/* Target Exam Card */}
          <div className="bg-white rounded-2xl p-5 shadow-md border border-border flex flex-col relative overflow-hidden">
             <div className="absolute top-0 right-0 p-3 opacity-[0.03] text-primary">
               <Icon i="target" size={80} />
             </div>
             <p className="text-muted-foreground text-xs font-semibold uppercase tracking-wider mb-1">{t('Target Exam')}</p>
             <h2 className="text-xl font-bold font-headings text-foreground">{t('SSC CGL 2024')}</h2>
             <div className="mt-4 flex items-center justify-between">
               <span className="text-sm font-medium text-muted-foreground">{t('Phase 1')}</span>
               <button className="bg-primary/10 text-primary px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wide">
                 {t('Change')}
               </button>
             </div>
          </div>

          {/* Daily Streak */}
          <div className="bg-white rounded-2xl p-4 shadow-sm border border-border flex items-center gap-4">
            <div className="bg-orange-50 text-orange-600 p-2.5 rounded-xl">
              <Icon i="flame" size={24} />
            </div>
            <div className="flex-1">
              <div className="flex justify-between items-center mb-1">
                <span className="font-bold text-foreground text-sm">{t('5 Day Streak')}</span>
                <span className="text-xs text-muted-foreground">{t('Keep it up!')}</span>
              </div>
              <div className="h-2 w-full bg-muted rounded-full overflow-hidden">
                <div className="h-full bg-orange-500 w-[70%] rounded-full"></div>
              </div>
            </div>
          </div>

          {/* AI Recommendation Banner */}
          <div className="bg-gradient-to-r from-indigo-50 to-purple-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm relative overflow-hidden">
             <div className="bg-white text-indigo-600 p-2 rounded-full shadow-sm mt-1 z-10">
               <Icon i="sparkles" size={16} />
             </div>
             <div className="flex-1 z-10">
               <p className="font-bold text-indigo-900 text-sm mb-1">{t('AI Recommendation')}</p>
               <p className="text-xs text-indigo-800 mb-3">{t('Try the latest SSC Mock Test to improve Quantitative Aptitude.')}</p>
               <button className="bg-indigo-600 text-white px-4 py-1.5 rounded-lg font-medium text-xs shadow-sm inline-flex items-center gap-1">
                 {t('Start Test')} <Icon i="arrow-right" size={12} />
               </button>
             </div>
             <div className="absolute -right-4 -bottom-4 w-24 h-24 bg-indigo-200/50 rounded-full blur-2xl"></div>
          </div>

          {/* Practice & Tests Grid */}
          <div>
            <h3 className="text-base font-bold text-foreground mb-3 px-1">{t('Practice & Tests')}</h3>
            <div className="grid grid-cols-2 gap-3">
              {gridFeatures.map((feat, idx) => (
                <button key={idx} className="bg-white border border-border p-4 rounded-xl shadow-sm flex flex-col items-center justify-center text-center">
                  <div className={`${feat.bg} ${feat.color} p-3 rounded-full mb-2`}>
                    <Icon i={feat.icon} size={20} />
                  </div>
                  <span className="font-semibold text-xs text-foreground">{feat.title}</span>
                </button>
              ))}
            </div>
          </div>

          {/* AI Tools Horizontal Scroll */}
          <div>
            <div className="flex items-center justify-between mb-3 px-1">
              <h3 className="text-base font-bold text-foreground">{t('AI Tools')}</h3>
              <button className="text-primary text-xs font-bold">{t('View All')}</button>
            </div>
            <div className="flex gap-3 overflow-x-auto pb-2 -mx-4 px-4 snap-x no-scrollbar">
              <div className="min-w-[200px] snap-center bg-white border border-border p-4 rounded-xl shadow-sm flex flex-col gap-2">
                <div className="flex items-center gap-2">
                  <div className="bg-blue-50 text-blue-600 p-2 rounded-lg">
                    <Icon i="file-text" size={16} />
                  </div>
                  <h4 className="font-semibold text-sm">{t('Smart Notes')}</h4>
                </div>
                <p className="text-xs text-muted-foreground line-clamp-2">{t('Generate notes from any topic instantly.')}</p>
              </div>
              <div className="min-w-[200px] snap-center bg-white border border-border p-4 rounded-xl shadow-sm flex flex-col gap-2">
                <div className="flex items-center gap-2">
                  <div className="bg-purple-50 text-purple-600 p-2 rounded-lg">
                    <Icon i="search" size={16} />
                  </div>
                  <h4 className="font-semibold text-sm">{t('Paper Analyzer')}</h4>
                </div>
                <p className="text-xs text-muted-foreground line-clamp-2">{t('Analyze past trends with AI.')}</p>
              </div>
              <div className="min-w-[200px] snap-center bg-white border border-border p-4 rounded-xl shadow-sm flex flex-col gap-2">
                <div className="flex items-center gap-2">
                  <div className="bg-green-50 text-green-600 p-2 rounded-lg">
                    <Icon i="message-square" size={16} />
                  </div>
                  <h4 className="font-semibold text-sm">{t('Doubt Solver')}</h4>
                </div>
                <p className="text-xs text-muted-foreground line-clamp-2">{t('Ask Riya your doubts.')}</p>
              </div>
            </div>
          </div>

          {/* Weak Topics Analysis */}
          <div className="bg-white border border-border rounded-2xl p-5 shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-foreground text-base">{t('Weak Topics')}</h3>
              <Icon i="bar-chart-2" size={18} className="text-muted-foreground" />
            </div>
            <div className="space-y-4">
              {weakTopics.map((topic, idx) => (
                <div key={idx}>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="font-medium text-foreground">{topic.subject}</span>
                    <span className="text-muted-foreground font-semibold">{topic.score}%</span>
                  </div>
                  <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                    <div className={`h-full ${topic.color} rounded-full`} style={{ width: `${topic.score}%` }}></div>
                  </div>
                </div>
              ))}
            </div>
            <button className="w-full mt-5 py-2.5 bg-primary/10 text-primary font-bold rounded-lg text-xs hover:bg-primary/20 transition-colors">
              {t('Improve Now')}
            </button>
          </div>

        </div>
      </main>

      {/* Bottom Nav */}
      <div className="flex items-center justify-between px-2 py-2 bg-white border-t border-border z-20 pb-safe">
        {[
          { name: t('Home'), icon: 'home' },
          { name: t('Tests'), icon: 'file-text' },
          { name: t('AI Tools'), icon: 'bot' },
          { name: t('Results'), icon: 'pie-chart' },
          { name: t('Profile'), icon: 'user' },
        ].map((tab) => {
          const isActive = tab.name === t('Home');
          return (
            <button 
              key={tab.name}
              className={`flex flex-col items-center justify-center w-full py-1.5 gap-1 rounded-xl transition-colors ${
                isActive ? 'text-primary' : 'text-muted-foreground hover:bg-muted/50'
              }`}
            >
              <div className={`p-1.5 rounded-full ${isActive ? 'bg-primary/10' : 'bg-transparent'}`}>
                <Icon i={tab.icon} size={20} className={isActive ? 'fill-primary/20' : ''} />
              </div>
              <span className={`text-[10px] ${isActive ? 'font-bold' : 'font-medium'}`}>
                {tab.name}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}",
      "genType": "components"
    }
  ],
  "sharedFiles": [
    {
      "path": "/style.css",
      "content": "@theme {
  /* used via utility-classes, bg-background, text-primary, and many more */
  --color-background: #ffffff;
  --color-foreground: #435f96;
  --color-border: #e2e8f0;
  --color-input: #f8fafc;
  --color-primary: #1a55b4;
  --color-primary-foreground: #ffffff;
  --color-secondary: #eff6ff;
  --color-secondary-foreground: #1e40af;
  --color-muted: #f1f5f9;
  --color-muted-foreground: #64748b;

  /* Semantic Status Colors */
  --color-error: #ef4444;
  --color-error-foreground: #ffffff;
  --color-error-muted: #fef2f2;
  --color-success: #10b981;
  --color-success-foreground: #ffffff;
  --color-success-muted: #ecfdf5;
  --color-warning: #f59e0b;
  --color-warning-text: #b45309;
  --color-warning-muted: #fef3c7;

  /* Premium Paywall Colors */
  --color-premium-bg: #0b0b1b;
  --color-premium-card: #020805;
  --color-premium-border: #dadae7;
  --color-premium-text: #ffffff;
  --color-premium-muted: #a1a1aa;
  --color-premium-gold: #fbbf24;
  --color-premium-gold-dark: #d97706;
  --color-premium-purple: #bca7cf;
  --color-premium-purple-light: #a855f7;

  /* DO NOT REMOVE: these radius variables are required by the theme editor. */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-2xl: 32px;

  /* DONT CHANGE OR REMOVE THIS VARIABLE */
