  /* DO NOT REMOVE: these font variables are required by the theme editor. */
  --font-body: Inter;
  --font-headings: Inter;

  /* Add and change text sizes as you see fit */
  --text-xs: 12px;
  --text-sm: 14px;
  --text-base: 16px;
  --text-lg: 18px;
  --text-xl: 20px;
  --text-2xl: 24px;
  --text-3xl: 30px;
  --text-4xl: 36px;
}"
    },
    {
      "path": "/components/TopNav.jsx",
      "content": "import Icon from '@global/Icon';

export default function TopNav() {
  return (
    <div className="flex items-center justify-between px-4 py-3 bg-primary text-primary-foreground shadow-sm">
      <div className="flex items-center gap-3">
        <button className="p-1">
          <Icon i="menu" size={24} />
        </button>
        <div className="flex items-center gap-2">
          <div className="bg-white/20 p-1.5 rounded-md">
            <Icon i="graduation-cap" size={20} />
          </div>
          <span className="font-headings font-semibold text-lg">{t('Sarkari Exam')}</span>
        </div>
      </div>

      <div className="flex items-center gap-4">
        <button className="flex items-center gap-1 text-sm bg-white/10 px-2 py-1 rounded-md">
          <Icon i="globe" size={16} />
          <span>{t('EN')}</span>
        </button>
        <button className="text-sm font-medium">
          {t('Login')}
        </button>
      </div>
    </div>
  );
}"
    },
    {
      "path": "/components/BottomNav.jsx",
      "content": "import Icon from '@global/Icon';

export default function BottomNav({ activeTab = 'Home' }) {
  const tabs = [
    { name: t('Home'), icon: 'home' },
    { name: t('Mock Test'), icon: 'file-text' },
    { name: t('Note Gen'), icon: 'sparkles' },
    { name: t('Riya'), icon: 'bot' },
    { name: t('Analytics'), icon: 'bar-chart-2' },
  ];

  return (
    <div className="flex items-center justify-between px-2 py-2 bg-background border-t border-border shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] pb-safe">
      {tabs.map((tab) => {
        const isActive = activeTab === tab.name;
        return (
          <button 
            key={tab.name}
            className={`flex flex-col items-center justify-center w-full py-1 gap-1 rounded-md ${
              isActive ? 'text-primary' : 'text-muted-foreground'
            }`}
          >
            <div className={`p-1.5 rounded-full ${isActive ? 'bg-secondary' : 'bg-transparent'}`}>
              <Icon i={tab.icon} size={20} />
            </div>
            <span className="text-[10px] font-medium tracking-wide">
              {tab.name}
            </span>
          </button>
        );
      })}
    </div>
  );
}"
    }
  ]
}
